package com.hospital.appointment.service;

import com.hospital.appointment.client.DoctorServiceClient;
import com.hospital.appointment.client.PatientServiceClient;
import com.hospital.appointment.dto.AppointmentResponseDto;
import com.hospital.appointment.dto.DoctorDto;
import com.hospital.appointment.dto.PatientDto;
import com.hospital.appointment.model.Appointment;
import com.hospital.appointment.repository.AppointmentRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class AppointmentServiceTest {
    @Mock private AppointmentRepository appointmentRepository;
    @Mock private PatientServiceClient patientServiceClient;
    @Mock private DoctorServiceClient doctorServiceClient;
    @InjectMocks private AppointmentService appointmentService;

    // GreyTest trace: getAppointmentsByPatient | each repository result is enriched in order | BR-001 -> TP-006 -> TC-1525
    @Test
    void getAppointmentsByPatient_twoAppointments_enrichesInRepositoryOrder() {
        // Arrange
        Appointment first = new Appointment();
        first.setId(501L);
        first.setPatientId(71L);
        first.setDoctorId(82L);
        first.setAppointmentDate(LocalDate.of(2025, 6, 10));
        first.setAppointmentTime(LocalTime.of(9, 30));
        first.setStatus(Appointment.AppointmentStatus.SCHEDULED);
        first.setReason("Khám định kỳ");
        Appointment second = new Appointment();
        second.setId(502L);
        second.setPatientId(71L);
        second.setDoctorId(83L);
        second.setAppointmentDate(LocalDate.of(2025, 6, 11));
        second.setAppointmentTime(LocalTime.of(10, 15));
        second.setStatus(Appointment.AppointmentStatus.CONFIRMED);
        second.setReason("Đau ngực");
        second.setNotes("Theo dõi");
        when(appointmentRepository.findByPatientId(71L)).thenReturn(Arrays.asList(first, second));
        when(patientServiceClient.getPatientById(71L)).thenReturn(new PatientDto(71L, "An", "Nguyễn", "an@example.test", "0900000001"));
        when(doctorServiceClient.getDoctorById(82L)).thenReturn(new DoctorDto(82L, "Bình", "Trần", "Tim mạch", true));
        when(doctorServiceClient.getDoctorById(83L)).thenReturn(new DoctorDto(83L, "Hoa", "Phạm", "Nội khoa", true));

        // Act
        List<AppointmentResponseDto> results = appointmentService.getAppointmentsByPatient(71L);

        // Assert
        assertEquals(2, results.size());
        AppointmentResponseDto firstResult = results.get(0);
        assertEquals(501L, firstResult.getId());
        assertEquals(71L, firstResult.getPatientId());
        assertEquals("An Nguyễn", firstResult.getPatientName());
        assertEquals(82L, firstResult.getDoctorId());
        assertEquals("Dr. Bình Trần", firstResult.getDoctorName());
        assertEquals("Tim mạch", firstResult.getDoctorSpecialization());
        assertEquals(LocalDate.of(2025, 6, 10), firstResult.getAppointmentDate());
        assertEquals(LocalTime.of(9, 30), firstResult.getAppointmentTime());
        assertEquals(Appointment.AppointmentStatus.SCHEDULED, firstResult.getStatus());
        assertEquals("Khám định kỳ", firstResult.getReason());
        assertNull(firstResult.getNotes());
        assertNull(firstResult.getDiagnosis());
        assertNull(firstResult.getPrescription());
        assertNull(firstResult.getCreatedAt());
        assertNull(firstResult.getUpdatedAt());
        assertNull(firstResult.getCancelledAt());
        assertNull(firstResult.getCompletedAt());
        AppointmentResponseDto secondResult = results.get(1);
        assertEquals(502L, secondResult.getId());
        assertEquals(71L, secondResult.getPatientId());
        assertEquals("An Nguyễn", secondResult.getPatientName());
        assertEquals(83L, secondResult.getDoctorId());
        assertEquals("Dr. Hoa Phạm", secondResult.getDoctorName());
        assertEquals("Nội khoa", secondResult.getDoctorSpecialization());
        assertEquals(LocalDate.of(2025, 6, 11), secondResult.getAppointmentDate());
        assertEquals(LocalTime.of(10, 15), secondResult.getAppointmentTime());
        assertEquals(Appointment.AppointmentStatus.CONFIRMED, secondResult.getStatus());
        assertEquals("Đau ngực", secondResult.getReason());
        assertEquals("Theo dõi", secondResult.getNotes());
        assertNull(secondResult.getDiagnosis());
        assertNull(secondResult.getPrescription());
        assertNull(secondResult.getCreatedAt());
        assertNull(secondResult.getUpdatedAt());
        assertNull(secondResult.getCancelledAt());
        assertNull(secondResult.getCompletedAt());
        verify(appointmentRepository).findByPatientId(71L);
        verify(patientServiceClient).getPatientById(71L);
        verify(patientServiceClient).getPatientById(71L);
        verify(doctorServiceClient).getDoctorById(82L);
        verify(doctorServiceClient).getDoctorById(83L);
    }
}
